-- Phase 9a: a report is generated by a job, so a row must exist before its bytes do.
-- `template_version` names the definition that rendered it, `finished_at` when the job stopped working on it,
-- and `error_code`/`error_detail` say why it never became a document. The byte-shaped columns become nullable
-- because a PENDING row genuinely has no file yet, and the check below only judges them once the row claims
-- to be READY — the alternative, a zero-length placeholder, would state a size that was never measured.
-- No index is added: the history list pages newest-first over "reports_organisation_id_created_at_idx", which
-- already serves it, and a client polls one report by primary key rather than scanning by status.

-- AlterTable
ALTER TABLE "reports" ADD COLUMN "template_version" INTEGER NOT NULL DEFAULT 1;
ALTER TABLE "reports" ADD COLUMN "finished_at" TIMESTAMPTZ;
ALTER TABLE "reports" ADD COLUMN "error_code" TEXT;
ALTER TABLE "reports" ADD COLUMN "error_detail" TEXT;
ALTER TABLE "reports" ADD COLUMN "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP;

-- Every row that exists was written by the first version of its template, which is why the default above is 1.
ALTER TABLE "reports" ALTER COLUMN "data_snapshot" DROP NOT NULL;
ALTER TABLE "reports" ALTER COLUMN "storage_key" DROP NOT NULL;
ALTER TABLE "reports" ALTER COLUMN "sha256" DROP NOT NULL;
ALTER TABLE "reports" ALTER COLUMN "size" DROP NOT NULL;

-- DropConstraint
ALTER TABLE "reports" DROP CONSTRAINT "reports_check";

-- CreateConstraint
ALTER TABLE "reports" ADD CONSTRAINT "reports_check" CHECK (
  length(btrim("title")) BETWEEN 1 AND 200
  AND length(btrim("template")) BETWEEN 1 AND 64
  AND "template_version" >= 1
  AND (
    "status" <> 'READY'
    OR (
      length(btrim("storage_key")) > 0
      AND "sha256" ~ '^[0-9a-f]{64}$'
      AND "size" > 0
      AND "data_snapshot" IS NOT NULL
    )
  )
  AND (
    "status" <> 'FAILED'
    OR (length(btrim("error_code")) BETWEEN 1 AND 64 AND "finished_at" IS NOT NULL)
  )
  AND ("error_detail" IS NULL OR length("error_detail") <= 2000)
);
